a=json.loads((D/'archive_index.json').read_text());files={r['path']:r for r in a['files']};omitted={r['path']:r for r in a['omitted_public_matrices']};counts={}
def check(path,digest,kind):
 name=str(path.relative_to(W));row=files.get(name) or omitted.get(name)
 assert row is not None and row['sha256']==digest,(name,'missing archive coverage or hash mismatch')
 counts[kind]=counts.get(kind,0)+1
suite=json.loads((P/'suite-integrity.json').read_text())
for row in suite['full_run_checks']:
 for name,h in row['output_sha256'].items():check(P/'full'/row['path']/name,h,'full_raw_files')
for row in suite['window_checks']:
 folder=P/'full'/row['path']
 for f in folder.iterdir():
  if f.is_file():check(f,hashlib.sha256(f.read_bytes()).hexdigest(),'window_files')
focused=0
for marker in (P/'checkpoint/runs').rglob('standard_eval.csv'):
 folder=marker.parent
 if not (folder/'00_config.json').is_file() or not (folder/'final_state.csv').is_file():continue
 focused+=1
 for f in folder.iterdir():
  if f.is_file():check(f,hashlib.sha256(f.read_bytes()).hexdigest(),'focused_raw_files')
assert focused==45
for study in ['s5','s10','s20','pilot','legacy']:
 root=W/'market_results/phase16'/study;m=json.loads((root/'manifest.json').read_text());check(root/'manifest.json',hashlib.sha256((root/'manifest.json').read_bytes()).hexdigest(),'study_manifests')
 for e in m['runs']:
  for name,h in e['output_sha256'].items():check(Path(e['output'])/name,h,'real_raw_files')
for root in sorted((W/'market_inputs/phase16').iterdir()):
 m=json.loads((root/'manifest.json').read_text())
 for name,h in m['output_sha256'].items():check(root/name,h,'input_files')
for label in ['checkpoint','full']:
 root=P/label/'source';s=json.loads((root/'source_record.json').read_text())
 for name,h in s['code_files_sha256'].items():check(root/name,h,'source_files')
 for f in (root/'configs').glob('*.json'):check(f,hashlib.sha256(f.read_bytes()).hexdigest(),'configuration_files')
record=dict(all_recorded_full_real_input_source_bytes_restorable=True,archive_sha256=a['sha256'],counts=counts,verifier_source=Path(__file__).read_text(),method='Each recorded file SHA must match a byte-readback-verified archive member or an exact canonical-matrix restore entry')
(D/'archive_coverage_checks.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(counts));print('All recorded raw/source/input/configuration files have exact verified archive coverage.')
